package com.hms.auth;
import com.hms.staff.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class StaffAuthService {private final HospitalStaffRepository staff;private final PasswordEncoder encoder;private final String secret;public StaffAuthService(HospitalStaffRepository s,PasswordEncoder e,org.springframework.core.env.Environment env){staff=s;encoder=e;secret=env.getProperty("HMS_AUTH_SECRET","development-only-change-me");} public void activate(UUID id,String password){HospitalStaff member=staff.findById(id).orElseThrow(()->new IllegalArgumentException("Staff member not found"));member.setPasswordHash(encoder.encode(password));member.updateStatus(StaffStatus.ACTIVE);staff.save(member);} public AuthResponse login(LoginRequest r){HospitalStaff member=staff.findByEmail(r.email()).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(member.getStatus()!=StaffStatus.ACTIVE||member.getPasswordHash()==null||!encoder.matches(r.password(),member.getPasswordHash()))throw new IllegalArgumentException("Invalid credentials");long exp=Instant.now().plus(Duration.ofHours(8)).getEpochSecond();String payload=member.getId()+"|"+member.getTenantId()+"|"+member.getRole()+"|"+exp;return new AuthResponse(Base64.getUrlEncoder().withoutPadding().encodeToString((payload+"."+sign(payload)).getBytes(StandardCharsets.UTF_8)),"Bearer",28800,member.getDisplayName(),member.getRole().name());} private String sign(String v){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
